INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 22, 'theory', 'Квиз: планировщик, миграция, HA');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 22, 0, 'Как планировщик oVirt выбирает хост из кластера?', '["Сначала ранжирует веса, потом применяет фильтры", "Фильтры отбрасывают неподходящие хосты, а у оставшихся побеждает лучшая взвешенная сумма рангов", "Выбирается хост с наибольшим числом ядер", "Модули голосуют, побеждает большинство"]', 1, 'Фильтры жёсткие: они вычёркивают хосты, на которых запуск невозможен. Веса мягкие: каждый модуль ранжирует хосты, ранги умножаются на коэффициенты политики и складываются, побеждает хост с лучшим итогом.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 22, 1, 'У хоста 64 ГиБ памяти, оптимизация памяти кластера 150%, работающие ВМ занимают 70 ГиБ, резерв не учитываем. Поместится ли ещё ВМ на 30 ГиБ?', '["Да, физической памяти 64 ГиБ больше 30", "Да, но только если включить баллонинг", "Нет, оптимизация действует лишь на настольные ВМ", "Нет, планировочная память 96 ГиБ, остаётся 26 ГиБ, этого мало"]', 3, 'Планировочная память равна 64 × 1,5 = 96 ГиБ. Минус 70 ГиБ уже обещанных остаётся 26 ГиБ, а новой машине нужно 30 ГиБ, поэтому фильтр памяти хост отбросит.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 22, 2, 'В чём главный риск политики миграции post-copy?', '["Обрыв сети между хостами после переключения может потерять работающую ВМ", "Миграция никогда не сходится", "Простой всегда превышает минуту", "Нельзя мигрировать ВМ с большой памятью"]', 0, 'При post-copy ВМ уже работает на целевом хосте, а часть страниц ещё лежит на исходном. Если связь оборвалась, недостающие страницы взять неоткуда, и экземпляр теряется. Зато сходимость гарантирована.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 22, 3, 'Что даёт ВМ аренда (lease) на домене хранения?', '["Ускоряет миграцию", "Позволяет превысить лимит памяти", "Гарантирует, что ВМ не запущена в двух местах, и позволяет безопасно перезапустить её без ограждения хоста", "Заменяет резервные копии"]', 2, 'Аренду держит хост, на котором работает ВМ. Пока она жива, вторая копия не стартует; когда хост пропал и аренда истекла, менеджер может запустить машину в другом месте, не дожидаясь ограждения.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 22, 4, 'Какую политику устойчивости выбрать, чтобы при неработоспособном хосте мигрировали только критичные ВМ?', '["Мигрировать все ВМ", "Мигрировать только высокодоступные ВМ", "Не мигрировать ВМ", "Включить политику none"]', 1, 'Политика «мигрировать только высокодоступные» переносит ВМ с флажком высокой доступности, остальные остаются на хосте. Политика none относится к планировщику, а не к устойчивости.');
